import logging

import attr
from typing import List, Optional
from enum import Enum, unique

from .connection_details import SshServiceDetails
from .fhs import FHS
from .pdu import PduPort
from .system_module import SystemModule
from .sync_input import SyncInputSource
from .testpc import TestPc
from .radio import RU
from .optical_switch import SwitchChannel

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@unique
class TRSInterfaces(Enum):
    EIF1 = 'EIF1'
    EIF2 = 'EIF2'
    EIF3 = 'EIF3'
    EIF4 = 'EIF4'
    EIF5 = 'EIF5'


@unique
class SlotId(Enum):
    C1 = 'C1'
    C2 = 'C2'
    B1 = 'B1'
    B2 = 'B2'
    B3 = 'B3'
    B4 = 'B4'
    B5 = 'B5'
    B6 = 'B6'


@attr.s(cmp=False)
class CapacityUnit(object):
    """
    :param str addr: IP ADDRESS or FQDN
    :param Optional[str] hardware_type: hardware type, e.g. 'ABIL'
    :param Optional[str] hardware_version: hardware version, e.g. 'X21'
    :param Optional[str] serial_number: serial number of capacity unit
    :param Optional[str] product_code: product code of capacity unit
    :param Optional[PduPort] pdu_port: PDU port to which capacity unit is connected
                                       (external power source used i.e. for hot insert, hot remove)
    :param Optional[List[RU]] rus: rus to which capacity unit is connected
    :param Optional[SlotId] slot_id: id of slot where capacity unit is placed, one of SlotId
    :param Optional[List[FHS]] fhs: fhss to which capacity unit is connected
    :param Optional[List[SwitchChannel]] optical_switch_channels: optical switch channels connected to CapacityUnit

    +------------+------------+
    |AMIA slot numbers:       |
    +============+============+
    | B3         | B6         |
    +------------+------------+
    | B2         | B5         |
    +------------+------------+
    | B1         | B4         |
    +------------+------------+
    | C1         | C2         |
    +------------+------------+

    """
    addr = attr.ib(type=str)
    hardware_type = attr.ib(default=None, type=Optional[str])
    hardware_version = attr.ib(default=None, type=Optional[str])
    serial_number = attr.ib(default=None, type=Optional[str])
    product_code = attr.ib(default=None, type=Optional[str])
    pdu_port = attr.ib(default=None, type=Optional[PduPort])
    rus = attr.ib(default=None, type=Optional[List[RU]])
    slot_id = attr.ib(default=None, type=Optional[SlotId])
    fhs = attr.ib(default=None, type=Optional[List[FHS]])
    optical_switch_channels = attr.ib(default=None, type=Optional[List[SwitchChannel]])


# TODO: move it to system_module in next major release
@attr.s(cmp=False)
class CommonUnit(object):
    """
    Object representing common system module platform (Airscale or Flexi FCT)

    :param SshServiceDetails lmp_connection: Connection with Local Maintenance Port
    :param List[CapacityUnit] capacity_units: List of CapacityUnit class instance objects
    :param Optional[PduPort] pdu_port: PduPort class instance object
    :param Optional[str] hardware_type: hardware type, e.g. 'ASIK'
    :param Optional[str] hardware_version: hardware version, e.g. 'X21'
    :param Optional[str] serial_number: serial number of common unit
    :param Optional[str] product_code: product code of common unit
    :param Optional[SyncInputSource] sync_input: sync input source connected to SIN port
    :param Optional[str] mac_addr: hardware MAC address
    :param Optional[TestPc] test_pc: test pc details
    :param Optional[List[TRSInterfaces]] trs_connections: Used TRS interfaces, one of TRSInterfaces
    :param Optional[SlotId] slot_id: id of slot where common unit is placed, one of SlotId
    :param Optional[List[RU]] rus: rus to which common unit is connected - only for Flexi system modules
    :param Optional[List[SwitchChannel]] optical_switch_channels: optical switch channels-only for Flexi system modules

    +------------+------------+
    |AMIA slot numbers:       |
    +============+============+
    | B3         | B6         |
    +------------+------------+
    | B2         | B5         |
    +------------+------------+
    | B1         | B4         |
    +------------+------------+
    | C1         | C2         |
    +------------+------------+

    """
    lmp_connection = attr.ib(type=SshServiceDetails)
    capacity_units = attr.ib(type=List[CapacityUnit])
    pdu_port = attr.ib(default=None, type=PduPort)
    hardware_type = attr.ib(default=None, type=Optional[str])
    hardware_version = attr.ib(default=None, type=Optional[str])
    serial_number = attr.ib(default=None, type=Optional[str])
    product_code = attr.ib(default=None, type=Optional[str])
    sync_input = attr.ib(default=None, type=Optional[SyncInputSource])
    mac_addr = attr.ib(default=None, type=Optional[str])
    test_pc = attr.ib(default=None, type=Optional[TestPc])
    trs_connections = attr.ib(default=None, type=Optional[List[TRSInterfaces]])
    slot_id = attr.ib(default=None, type=Optional[SlotId])
    rus = attr.ib(default=None, type=Optional[List[RU]])
    optical_switch_channels = attr.ib(default=None, type=Optional[List[SwitchChannel]])


@attr.s(cmp=False)
class CoreUnit(object):
    """
    Object representing core modules, e.g. 'ASOE'

    :param SshServiceDetails lmp_connection: Connection with Local Maintenance Port
    :param Optional[PduPort] pdu_port: PduPort class instance object
    :param Optional[str] hardware_type: hardware type, e.g. 'ASIK'
    :param Optional[str] hardware_version: hardware version, e.g. 'X21'
    :param Optional[str] serial_number: serial number of core unit
    :param Optional[SyncInputSource] sync_input: sync input source connected to SIN port
    :param Optional[str] mac_addr: hardware MAC address
    :param Optional[TestPc] test_pc: test pc details
    :param Optional[List[TRSInterfaces]] trs_connections: Used TRS interfaces, one of TRSInterfaces
    :param Optional[List[RU]] rus: rus to which core unit is connected
    :param Optional[List[FHS]] fhs: fhss to which capacity unit is connected
    :param Optional[List[SwitchChannel]] optical_switch_channels: optical switch channels connected to CoreUnit
    """
    lmp_connection = attr.ib(type=SshServiceDetails)
    pdu_port = attr.ib(default=None, type=PduPort)
    hardware_type = attr.ib(default=None, type=Optional[str])
    hardware_version = attr.ib(default=None, type=Optional[str])
    serial_number = attr.ib(default=None, type=Optional[str])
    sync_input = attr.ib(default=None, type=Optional[SyncInputSource])
    mac_addr = attr.ib(default=None, type=Optional[str])
    test_pc = attr.ib(default=None, type=Optional[TestPc])
    trs_connections = attr.ib(default=None, type=Optional[List[TRSInterfaces]])
    rus = attr.ib(default=None, type=Optional[List[RU]])
    fhs = attr.ib(default=None, type=Optional[List[FHS]])
    optical_switch_channels = attr.ib(default=None, type=Optional[List[SwitchChannel]])


@attr.s(cmp=False)
class Airscale(SystemModule):
    """
    Object representing baseband platform and its plugins according
    (Airscale Radio Naming Guidance)


    :param Optional[List[CommonUnit]] common_units: List of CommonUnit class instance objects
    :param Optional[List[CoreUnit]] core_units: List of CoreUnit class instance objects
    :param Optional[str] product_code: product code of Airscale
    """
    common_units = attr.ib(default=None, type=List[CommonUnit])
    core_units = attr.ib(default=None, type=List[CoreUnit])
    product_code = attr.ib(default=None, type=Optional[str])

    def __attrs_post_init__(self):
        if not self.common_units and not self.core_units:
            logger.warning('At least one common unit or core unit have to be defined.')
